insert into public.facts
  (id, title, category, short_text, long_text, source_label, source_url, quiz, status, created_at)
values
  ('seed-001', 'Dzień dłuższy niż rok', 'Kosmos', 'Jeden obrót Wenus wokół własnej osi trwa dłużej niż jej okrążenie wokół Słońca.', 'Wenus obraca się wokół własnej osi tak wolno, że jeden obrót zajmuje jej około 243 ziemskich dni, a okrążenie Słońca tylko około 225. Doba gwiazdowa na Wenus jest więc dłuższa niż tamtejszy rok.

Planeta kręci się też w przeciwną stronę niż większość planet Układu Słonecznego, więc Słońce wschodziłoby tam na zachodzie. Czas od wschodu do wschodu Słońca wynosi około 117 ziemskich dni.', 'NASA', 'https://science.nasa.gov/venus/', '{"question": "Co na Wenus trwa dłużej?", "options": ["Okrążenie Słońca", "Jeden obrót wokół własnej osi", "Oba trwają dokładnie tyle samo"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-002', 'Lodowe góry Plutona', 'Kosmos', 'Na Plutonie wznoszą się góry z lodu wodnego wysokie na około 3,5 km.', 'Sonda New Horizons sfotografowała góry Plutona podczas przelotu w lipcu 2015 roku. Przy temperaturze około minus 230 stopni Celsjusza lód wodny jest twardy jak skała, dlatego może tworzyć masywy o wysokości około 3,5 km.

Obok nich rozciąga się Sputnik Planitia, rozległa równina pokryta głównie lodem azotowym. Jej gładka powierzchnia wskazuje, że Pluton jest geologicznie aktywniejszy, niż przypuszczano przed misją.', 'NASA', 'https://science.nasa.gov/dwarf-planets/pluto/', '{"question": "Z czego zbudowane są góry na Plutonie?", "options": ["Z lodu wodnego", "Z zastygłej lawy", "Z żelaza"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-003', 'Trzy serca ośmiornicy', 'Zwierzęta', 'Ośmiornica ma trzy serca i niebieską krew.', 'Dwa serca ośmiornicy pompują krew przez skrzela, a trzecie rozprowadza ją po reszcie ciała. Serce główne zatrzymuje się podczas pływania, dlatego ośmiornice często wolą pełzać, bo pływanie szybko je męczy.

Krew jest niebieska, bo tlen przenosi w niej hemocyjanina zawierająca miedź, a nie hemoglobina zawierająca żelazo. Dobrze sprawdza się ona w zimnej wodzie o niskiej zawartości tlenu.', 'Smithsonian Ocean, „Cephalopods”', null, '{"question": "Dlaczego krew ośmiornicy jest niebieska?", "options": ["Zawiera dużo żelaza", "Zawiera barwnik z pożywienia", "Tlen przenosi w niej białko z miedzią"], "correctIndex": 2}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-004', 'Sześcienne odchody wombata', 'Zwierzęta', 'Wombaty wydalają odchody w kształcie niemal sześciennych kostek.', 'Kostki pomagają wombatom znaczyć terytorium: układane na skałach i kłodach nie staczają się tak łatwo jak kulki.

Badacze ustalili, że kształt powstaje w jelitach. Ich ściany mają obszary o różnej sztywności, które podczas powolnego przesuwania treści formują płaskie boki i narożniki.', 'Yang i in., „Intestines of non-uniform stiffness mold the corners of wombat feces”, Soft Matter, 2021', null, '{"question": "Gdzie powstaje sześcienny kształt odchodów wombata?", "options": ["W jelitach", "W norze, pod naciskiem ziemi", "Na powierzchni skał"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-005', 'Kleopatra bliżej Apollo niż piramid', 'Historia', 'Kleopatra żyła bliżej lądowania na Księżycu niż budowy Wielkiej Piramidy.', 'Wielka Piramida w Gizie powstała około 2560 roku p.n.e., a Kleopatra żyła w I wieku p.n.e. Dzieli je około 2500 lat, czyli więcej niż około 2000 lat między Kleopatrą a lądowaniem Apollo 11 w 1969 roku.

Za czasów Kleopatry piramidy były już starożytnymi zabytkami, a Egiptem rządziła grecka dynastia Ptolemeuszy.', 'Encyclopaedia Britannica, hasła „Pyramids of Giza” i „Cleopatra”', null, '{"question": "Które wydarzenie było bliżej czasów Kleopatry?", "options": ["Budowa Wielkiej Piramidy", "Lądowanie Apollo 11 na Księżycu", "Oba były tak samo odległe"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-006', 'Najkrótsza wojna w historii', 'Historia', 'Wojna brytyjsko-zanzibarska z 1896 roku trwała około 40 minut.', 'Po śmierci sułtana Zanzibaru w sierpniu 1896 roku władzę przejął Khalid bin Barghash, którego nie zaakceptowali Brytyjczycy. Postawili mu ultimatum, a gdy minęło, rankiem 27 sierpnia rozpoczęli ostrzał pałacu.

Walki zakończyły się po około 40 minutach. Uważa się je za najkrótszą wojnę w zapisanej historii.', 'Guinness World Records, „Shortest war”', null, '{"question": "Ile trwała wojna brytyjsko-zanzibarska?", "options": ["Około 40 dni", "Około 4 godzin", "Około 40 minut"], "correctIndex": 2}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-007', 'Efekt Zeigarnik', 'Psychologia', 'Zadania przerwane często pamiętamy lepiej niż ukończone.', 'Zjawisko opisała w latach 20. XX wieku psycholożka Bluma Zeigarnik. W jej eksperymencie uczestnicy lepiej przypominali sobie zadania, które im przerwano, niż te, które zdążyli skończyć.

Późniejsze badania nie zawsze potwierdzały siłę tego efektu, ale wciąż jest on często przywoływany przy omawianiu motywacji i planowania pracy.', 'Bluma Zeigarnik, „Das Behalten erledigter und unerledigter Handlungen”, Psychologische Forschung, 1927', null, '{"question": "Jakie zadania według efektu Zeigarnik pamiętamy lepiej?", "options": ["Przerwane", "Ukończone", "Wykonane w grupie"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-008', 'Efekt potwierdzenia', 'Psychologia', 'Chętniej zauważamy i zapamiętujemy informacje zgodne z tym, w co już wierzymy.', 'Efekt potwierdzenia sprawia, że dwie osoby mogą przeczytać ten sam tekst i uznać, że potwierdza ich przeciwne poglądy.

W klasycznym badaniu z 1979 roku zwolennicy i przeciwnicy kary śmierci oceniali te same materiały. Obie grupy uznały dane zgodne ze swoim stanowiskiem za bardziej wiarygodne, a ich poglądy jeszcze się spolaryzowały.', 'Raymond S. Nickerson, „Confirmation Bias: A Ubiquitous Phenomenon in Many Guises”, Review of General Psychology, 1998', null, '{"question": "Co wynika z efektu potwierdzenia?", "options": ["Lepiej pamiętamy nowe nazwiska", "Bardziej ufamy danym zgodnym z naszymi poglądami", "Zapominamy wydarzenia z dzieciństwa"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-009', 'Pierwszy błąd komputerowy', 'Technologia', 'W 1947 roku w komputerze Harvard Mark II znaleziono ćmę uwięzioną w przekaźniku.', 'Operatorzy wkleili ćmę do dziennika pracy z dopiskiem o pierwszym prawdziwym przypadku znalezienia „buga”. Historię spopularyzowała Grace Hopper, która pracowała przy tym komputerze.

Samo słowo było jednak używane już wcześniej: inżynierowie, w tym Thomas Edison, nazywali tak usterki już w XIX wieku. Strona dziennika z ćmą trafiła do zbiorów Smithsonian.', 'Smithsonian National Museum of American History, „Log Book With Computer Bug”', null, '{"question": "Co znaleziono w przekaźniku komputera Harvard Mark II?", "options": ["Mysz", "Pająka", "Ćmę"], "correctIndex": 2}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-010', 'Plecione oprogramowanie Apollo', 'Technologia', 'Program komputera Apollo zapisywano fizycznie, przeplatając druty przez magnetyczne rdzenie.', 'Komputer pokładowy statków Apollo miał około 2 tysięcy słów pamięci RAM i 36 tysięcy słów pamięci stałej, czyli odpowiednio około 4 KB i 72 KB.

Pamięć stała miała postać plecionki: drut przechodzący przez rdzeń oznaczał jedynkę, a omijający go zero. Wplatały go ręcznie pracownice fabryki, a po utkaniu programu nie dało się już zmienić.', 'Eldon C. Hall, „Journey to the Moon: The History of the Apollo Guidance Computer”, AIAA, 1996', null, '{"question": "Jak zapisywano program komputera Apollo?", "options": ["Na taśmie magnetycznej", "Przeplatając druty przez rdzenie", "Na dyskach twardych"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-011', 'Ślady na miliony lat', 'Kosmos', 'Odciski butów astronautów mogą przetrwać na Księżycu miliony lat.', 'Księżyc nie ma atmosfery, wiatru ani płynącej wody, więc nic nie zaciera śladów pozostawionych w pyle przez misje Apollo.

Powierzchnię zmieniają tam głównie mikrometeoryty, a ten proces jest niezwykle powolny.', 'NASA', 'https://science.nasa.gov/moon/', '{"question": "Dlaczego ślady astronautów przetrwają tak długo?", "options": ["Księżyc nie ma wiatru ani wody", "Pył księżycowy twardnieje jak beton", "Chroni je pole magnetyczne"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-012', 'Siedem kręgów żyrafy', 'Zwierzęta', 'Żyrafa ma w szyi tyle samo kręgów co człowiek: siedem.', 'Niemal wszystkie ssaki mają siedem kręgów szyjnych. Szyja żyrafy nie zawdzięcza długości ich liczbie, lecz rozmiarowi, bo każdy z nich jest bardzo wydłużony.

Wyjątkami od tej reguły są między innymi leniwce i manaty.', 'Encyclopaedia Britannica, hasło „Giraffe”', null, '{"question": "Ile kręgów szyjnych ma żyrafa?", "options": ["Siedem", "Czternaście", "Dwadzieścia jeden"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-013', 'Uniwersytet starszy niż Aztekowie', 'Historia', 'W Oksfordzie nauczano już pod koniec XI wieku, ponad 200 lat przed założeniem stolicy Azteków.', 'Uniwersytet Oksfordzki podaje, że nauczanie odbywało się tam już w 1096 roku. Tenochtitlán, stolicę Azteków, założono dopiero około 1325 roku.

Oksford działał więc już od ponad dwóch stuleci, gdy na jeziorze Texcoco powstawało miasto, w którego miejscu stoi dziś Meksyk.', 'University of Oxford, „Introduction and history”', null, '{"question": "Co powstało wcześniej?", "options": ["Tenochtitlán", "Oba w tym samym stuleciu", "Nauczanie w Oksfordzie"], "correctIndex": 2}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-014', 'Efekt Dunninga-Krugera', 'Psychologia', 'Osoby słabe w danej dziedzinie często zawyżają ocenę własnych umiejętności.', 'W badaniu z 1999 roku David Dunning i Justin Kruger pokazali, że uczestnicy z najgorszymi wynikami w testach znacznie przeszacowywali swoje rezultaty.

Autorzy tłumaczyli to tym, że do rozpoznania braków potrzebne są te same umiejętności, których brakuje. Część badaczy spiera się o to, jak duża część efektu wynika ze statystyki.', 'Kruger i Dunning, „Unskilled and Unaware of It”, Journal of Personality and Social Psychology, 1999', null, '{"question": "Kto według efektu Dunninga-Krugera częściej się przecenia?", "options": ["Eksperci", "Osoby słabe w danej dziedzinie", "Osoby w podeszłym wieku"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-015', 'Pierwszy SMS', 'Technologia', 'Pierwszy SMS wysłano w 1992 roku i brzmiał „Merry Christmas”.', 'Wiadomość wysłał 3 grudnia 1992 roku inżynier Neil Papworth. Napisał ją na komputerze, bo ówczesne telefony nie pozwalały jeszcze tworzyć takich wiadomości, a trafiła na telefon Richarda Jarvisa z firmy Vodafone.

Odbiorca nie mógł odpisać, bo jego aparat tego nie obsługiwał.', 'BBC News, „Hppy bthdy txt!”, 2002', null, '{"question": "Jak brzmiał pierwszy SMS?", "options": ["Hello World", "Merry Christmas", "Happy New Year"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-016', 'Światło sprzed ośmiu minut', 'Kosmos', 'Światło Słońca dociera do Ziemi po około 8 minutach i 20 sekundach.', 'Słońce widzimy więc zawsze takim, jakie było ponad osiem minut wcześniej. Gdyby nagle zgasło, przez ten czas nie zauważylibyśmy niczego.

Droga światła z wnętrza gwiazdy na jej powierzchnię trwa natomiast znacznie dłużej, nawet tysiące lat, bo fotony są wciąż pochłaniane i wypromieniowywane na nowo.', 'NASA', 'https://science.nasa.gov/sun/', '{"question": "Ile w przybliżeniu leci światło ze Słońca na Ziemię?", "options": ["8 sekund", "8 minut", "8 godzin"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-017', 'Ptak, który lata do tyłu', 'Zwierzęta', 'Kolibry jako jedyne ptaki potrafią utrzymać lot do tyłu.', 'Skrzydła kolibra obracają się w barku, dzięki czemu wytwarzają siłę nośną zarówno przy ruchu w przód, jak i w tył. Pozwala to ptakom zawisać w miejscu przy kwiatach.

Najmniejsze gatunki wykonują kilkadziesiąt uderzeń skrzydeł na sekundę.', 'Encyclopaedia Britannica, hasło „Hummingbird”', null, '{"question": "Co wyróżnia lot kolibrów?", "options": ["Potrafią lecieć do tyłu", "Latają wyłącznie nocą", "Nie poruszają skrzydłami podczas lotu"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-018', 'Konstytucja 3 maja', 'Historia', 'Polska uchwaliła w 1791 roku pierwszą w Europie nowoczesną konstytucję.', 'Ustawa Rządowa przyjęta przez Sejm Czteroletni była pierwszą w Europie i drugą na świecie, po amerykańskiej, nowoczesną konstytucją pisaną.

Obowiązywała krótko, bo po wojnie w obronie konstytucji i konfederacji targowickiej została obalona w 1792 roku.', 'Encyclopaedia Britannica, hasło „Constitution of May 3, 1791”', null, '{"question": "Którą na świecie nowoczesną konstytucją była polska z 1791 roku?", "options": ["Pierwszą", "Drugą", "Piątą"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-019', 'Reguła szczytu i końca', 'Psychologia', 'Doświadczenia oceniamy głównie po ich najsilniejszym momencie i zakończeniu.', 'W badaniu Daniela Kahnemana uczestnicy trzymali rękę w bardzo zimnej wodzie. Dłuższą próbę oceniali lepiej od krótszej, jeśli na jej końcu temperatura lekko się podnosiła, choć łączny dyskomfort był większy.

Dlatego dobre zakończenie potrafi uratować wspomnienie całego wydarzenia.', 'Kahneman i in., „When More Pain Is Preferred to Less”, Psychological Science, 1993', null, '{"question": "Co najmocniej wpływa na wspomnienie doświadczenia?", "options": ["Jego łączny czas trwania", "Jego początek i środek", "Jego szczyt i zakończenie"], "correctIndex": 2}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-020', 'Mysz z drewna', 'Technologia', 'Pierwsza mysz komputerowa była drewnianym pudełkiem z dwoma kółkami.', 'Douglas Engelbart i Bill English zbudowali jej prototyp w latach 60. XX wieku. Dwa prostopadłe kółka odczytywały ruch w poziomie i w pionie.

Nazwa wzięła się podobno od kabla przypominającego ogon. Engelbart zaprezentował urządzenie publicznie w 1968 roku.', 'Computer History Museum, „The Mouse”', null, '{"question": "Z czego zrobiono obudowę pierwszej myszy komputerowej?", "options": ["Z aluminium", "Z drewna", "Z gumy"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-021', 'Saturn pływałby w wodzie', 'Kosmos', 'Średnia gęstość Saturna jest mniejsza niż gęstość wody.', 'Saturn składa się głównie z wodoru i helu, a jego średnia gęstość wynosi około 0,7 grama na centymetr sześcienny, podczas gdy woda ma około 1.

W wyobrażonym, dostatecznie wielkim oceanie planeta unosiłaby się więc na powierzchni. To jedyna taka planeta w Układzie Słonecznym.', 'NASA', 'https://science.nasa.gov/saturn/', '{"question": "Co jest niezwykłego w gęstości Saturna?", "options": ["Jest większa niż gęstość żelaza", "Jest mniejsza niż gęstość wody", "Jest równa gęstości Ziemi"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-022', 'Niezniszczalne niesporczaki', 'Zwierzęta', 'Niesporczaki przeżyły wystawienie na próżnię kosmiczną.', 'Te mikroskopijne zwierzęta potrafią wysychać i przechodzić w stan niemal całkowitego zatrzymania metabolizmu. W 2007 roku wysłano je na orbitę na zewnątrz kapsuły.

Część osobników przeżyła próżnię, a niektóre również silne promieniowanie ultrafioletowe Słońca.', 'Jönsson i in., „Tardigrades survive exposure to space in low Earth orbit”, Current Biology, 2008', null, '{"question": "Co przeżyły niesporczaki w 2007 roku?", "options": ["Wystawienie na próżnię kosmiczną", "Kilka lat w lawie", "Zanurzenie w kwasie azotowym"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-023', 'Wojna z emu', 'Historia', 'W 1932 roku australijscy żołnierze z karabinami maszynowymi przegrali z emu.', 'Tysiące emu niszczyły uprawy w Australii Zachodniej, więc rząd wysłał żołnierzy z dwoma karabinami maszynowymi Lewisa.

Ptaki rozpraszały się i uciekały poza zasięg ognia. Akcję przerwano po kilku tygodniach, a jej skutki były tak słabe, że wyśmiewała ją prasa.', 'National Museum of Australia, „Emu War”', null, '{"question": "Jak zakończyła się australijska wojna z emu?", "options": ["Wytępieniem emu", "Przerwaniem akcji bez sukcesu", "Budową muru na całą Australię"], "correctIndex": 1}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-024', 'Niewidzialny goryl', 'Psychologia', 'W słynnym eksperymencie około połowa osób nie zauważyła człowieka w stroju goryla.', 'Uczestnicy oglądali film i liczyli podania koszykarzy. W tym czasie przez scenę przechodziła osoba przebrana za goryla, a wielu widzów w ogóle jej nie dostrzegło.

Zjawisko nazywa się ślepotą z nieuwagi. Skupienie na jednym zadaniu może sprawić, że nie widzimy czegoś oczywistego.', 'Simons i Chabris, „Gorillas in our midst”, Perception, 1999', null, '{"question": "Co liczyli uczestnicy eksperymentu z gorylem?", "options": ["Podania koszykarzy", "Osoby w czerwonych koszulkach", "Sekundy trwania filmu"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-025', 'Polacy i Enigma', 'Technologia', 'Enigmę jako pierwsi złamali Polacy, siedem lat przed wybuchem wojny.', 'W 1932 roku Marian Rejewski, korzystając z matematyki, odtworzył działanie niemieckiej maszyny szyfrującej. Z Jerzym Różyckim i Henrykiem Zygalskim opracowali potem metody i urządzenia do odczytywania szyfrów.

W lipcu 1939 roku Polacy przekazali swoje osiągnięcia Francuzom i Brytyjczykom, co pomogło późniejszym pracom w Bletchley Park.', 'Encyclopaedia Britannica, hasło „Enigma”', null, '{"question": "Kto jako pierwszy złamał szyfr Enigmy?", "options": ["Polscy matematycy", "Amerykańscy inżynierowie", "Francuscy szpiedzy"], "correctIndex": 0}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-026', 'Najwyższa góra planet', 'Kosmos', 'Olympus Mons na Marsie jest niemal dwa i pół raza wyższy od Mount Everestu.', 'Ten wygasły wulkan tarczowy wznosi się na blisko 22 km i należy do najwyższych szczytów w Układzie Słonecznym.

Urósł tak bardzo, bo na Marsie nie ma ruchu płyt tektonicznych, więc lawa przez bardzo długi czas wypływała w tym samym miejscu, a niższa grawitacja pozwalała górze rosnąć.', 'NASA', 'https://science.nasa.gov/mars/', '{"question": "Na jakiej planecie leży Olympus Mons?", "options": ["Na Wenus", "Na Merkurym", "Na Marsie"], "correctIndex": 2}'::jsonb, 'published', '2026-01-01T00:00:00.000Z'),
  ('seed-027', 'Różowe od jedzenia', 'Zwierzęta', 'Flamingi zawdzięczają kolor swojej diecie, a nie genom.', 'W skorupiakach i glonach, którymi żywią się flamingi, znajdują się karotenoidy. Organizm przekształca je w barwniki odkładane w piórach.

